int register_genl_family(struct genl_family *family)
{
    int err;

    if (!family || !family->ops || !family->name || family->id != GENL_ID_UNSPEC) {
        return -EINVAL;
    }

    mutex_lock(&genl_mutex);

    if (genl_find_family(family->name)) {
        mutex_unlock(&genl_mutex);
        return -EEXIST;
    }

    if (family->id == GENL_ID_UNSPEC) {
        for (family->id = 1; family->id < GENL_MAX_ID; family->id++) {
            if (!genl_families[family->id]) {
                break;
            }
        }
        if (family->id >= GENL_MAX_ID) {
            mutex_unlock(&genl_mutex);
            return -ENOMEM;
        }
    } else {
        if (genl_families[family->id]) {
            mutex_unlock(&genl_mutex);
            return -EBUSY;
        }
    }

    genl_families[family->id] = family;

    if (family->n_attrs && !family->attrbuf) {
        family->attrbuf = kmalloc(family->n_attrs * sizeof(void *), GFP_KERNEL);
        if (!family->attrbuf) {
            genl_families[family->id] = NULL;
            mutex_unlock(&genl_mutex);
            return -ENOMEM;
        }
    }

    for (int i = 0; i < family->n_mcgrps; i++) {
        if (!family->mcgrps[i].name || !family->mcgrps[i].id) {
            err = -EINVAL;
            goto error;
        }

        if (family->mcgrps[i].id >= GENL_MAX_MCGRP) {
            err = -ENOMEM;
            goto error;
        }
    }

    mutex_unlock(&genl_mutex);
    genl_notify_family_registered(family);
    return 0;

error:
    genl_families[family->id] = NULL;
    if (family->attrbuf) {
        kfree(family->attrbuf);
    }
    mutex_unlock(&genl_mutex);
    return err;
}

int genl_register_family(struct genl_family *family) {
    int err;

    if (!family || !family->n_ops || !family->name)
        return -EINVAL;

    if (genl_validate_ops(family))
        return -EINVAL;

    genl_lock_all_families();

    if (genl_family_find(family->name)) {
        genl_unlock_all_families();
        return -EEXIST;
    }

    if (family->id == 0)
        family->id = genl_get_free_id();

    if (family->maxattr && !family->ops.alloc_attr) {
        family->ops.alloc_attr = kmalloc(family->maxattr * sizeof(void *), GFP_KERNEL);
        if (!family->ops.alloc_attr) {
            genl_unlock_all_families();
            return -ENOMEM;
        }
    }

    if (family->n_mcgrps && genl_validate_mcgrps(family)) {
        genl_unlock_all_families();
        return -EINVAL;
    }

    list_add_tail(&family->list, &genl_family_list);

    genl_unlock_all_families();

    genl_notify_family_registered(family);

    return 0;
}

int genl_register_family(struct genl_family *family) {
    int err;

    if (!family)
        return -EINVAL;

    if (family->version == 0)
        family->version = 1;

    if (family->maxattr == 0)
        family->maxattr = 1;

    if (!family->ops || family->n_ops <= 0)
        return -EINVAL;

    for (int i = 0; i < family->n_ops; i++) {
        struct genl_ops *op = &family->ops[i];
        if (!op->doit && !op->dumpit)
            return -EINVAL;
    }

    write_lock(&genl_mutex);

    if (genl_fam_by_name(family->name))
        return -EEXIST;

    if (family->id) {
        if (genl_fam_by_id(family->id))
            return -EEXIST;
    } else {
        family->id = genl_get_free_id();
        if (family->id == 0)
            return -ENOSPC;
    }

    if (family->n_attrs) {
        family->attrs = kzalloc((family->maxattr + 1) * sizeof(void *), GFP_KERNEL);
        if (!family->attrs) {
            err = -ENOMEM;
            goto out_unlock;
        }
    }

    family->mcgrps = kzalloc(family->n_mcgrps * sizeof(struct genl_multicast_group), GFP_KERNEL);
    if (!family->mcgrps) {
        err = -ENOMEM;
        goto out_unlock;
    }

    for (int i = 0; i < family->n_mcgrps; i++) {
        struct genl_multicast_group *grp = &family->mcgrps[i];
        if (strlen(grp->name) == 0) {
            err = -EINVAL;
            goto out_free_mcgrps;
        }
        if (grp->id == 0)
            grp->id = i + 1;
    }

    list_add_tail(&family->list, &genl_families);

    genl_notify_family_registered(family);

    write_unlock(&genl_mutex);
    return 0;

out_free_mcgrps:
    kfree(family->mcgrps);
out_unlock:
    write_unlock(&genl_mutex);
    return err;
}

int genl_register_family(struct genl_family *family)
{
    int err;

    /* Validate operations */
    if (!family->version || !family->n_attrs || !family->max_attrs) {
        return -EINVAL;
    }

    /* Lock all generic netlink families */
    mutex_lock(&genl_mutex);

    /* Check for duplicate family name */
    if (genl_find_family(family->name)) {
        mutex_unlock(&genl_mutex);
        return -EEXIST;
    }

    /* Handle special cases for ID allocation if needed */
    if (family->id == 0) {
        for (int i = 0; i < GENL_NFPROTO; i++) {
            for (int j = 0; j < GENL_ID_ALLOC; j++) {
                if (!genl_families[i][j]) {
                    family->id = j;
                    break;
                }
            }
            if (family->id != 0) {
                break;
            }
        }
        if (family->id == 0) {
            mutex_unlock(&genl_mutex);
            return -ENOSPC;
        }
    }

    /* Allocate memory for attributes if needed */
    if (!family->ops) {
        family->ops = kzalloc(family->n_attrs * sizeof(struct genl_ops), GFP_KERNEL);
        if (!family->ops) {
            mutex_unlock(&genl_mutex);
            return -ENOMEM;
        }
    }

    /* Assign family and store it in the family table */
    genl_families[family->id] = family;

    /* Validate multicast groups */
    for (int i = 0; i < family->n_multicast_groups; i++) {
        if (family->mcgrps[i].name == NULL || family->mcgrps[i].id >= GENL_MAX_MC_GROUPS) {
            err = -EINVAL;
            goto out_unregister;
        }
    }

    /* Send events to notify about new family and its groups */
    genl_notify_family_registered(family);

    mutex_unlock(&genl_mutex);
    return 0;

out_unregister:
    genl_families[family->id] = NULL;
    mutex_unlock(&genl_mutex);
    kfree(family->ops);
    return err;
}

int genl_register_family(struct genl_family *family)
{
    int err = 0;

    if (!family)
        return -EINVAL;

    if (family->n_ops) {
        int i;
        for (i = 0; i < family->n_ops; i++) {
            if (!family->ops[i].doit && !family->ops[i].dumpit)
                return -EINVAL;
        }
    }

    write_lock(&genl_mutex);

    if (genl_family_find(family->name)) {
        write_unlock(&genl_mutex);
        return -EEXIST;
    }

    if (!family->id) {
        if (genl_family_id == GENL_ID_MAX) {
            write_unlock(&genl_mutex);
            return -ENOSPC;
        }
        family->id = ++genl_family_id;
    } else {
        if (family->id > GENL_ID_MAX) {
            write_unlock(&genl_mutex);
            return -EINVAL;
        }
    }

    if (family->n_attrs) {
        int i;
        family->attrbuf = kmalloc(family->n_attrs * sizeof(void *), GFP_KERNEL);
        if (!family->attrbuf) {
            write_unlock(&genl_mutex);
            return -ENOMEM;
        }
        for (i = 0; i < family->n_attrs; i++)
            family->attrbuf[i] = NULL;
    }

    list_add_tail(&family->list, &genl_fam_list);
    write_unlock(&genl_mutex);

    err = genl_notify_family(family, NULL, 0, 0);
    if (err < 0)
        return err;

    return 0;
}
